select count(*) as failures from (
select avg((x > 0)::integer) as share_in_attacking_half
from {{ ref('flames_shots') }}
where event <> 'blocked-shot'
having avg((x > 0)::integer) < 0.95
) dbt_test

select count(*) as failures from (
select * from {{ ref('flames_games') }} where not (points = case result when 'W' then 2 when 'OTL' then 1 else 0 end)
) dbt_test

select count(*) as failures from (
select * from {{ ref('flames_shots') }} where not (x between -100 and 100 and y between -43 and 43)
) dbt_test

select count(*) as failures from (
select shooter
from {{ ref('flames_shots') }}
where shooter is null
) dbt_test

select count(*) as failures from (
select count(*) as row_count from {{ ref('flames_games') }} having count(*) < 82
) dbt_test
